<?php use Luna\Core\Csrf; use Luna\Core\View; ?>
<section class="page-intro compact"><div><a class="back-link" href="/accounting/journal">← Prima nota</a><span class="eyebrow">Registrazione <?= View::e($entry['protocol_number']) ?></span><h1><?= View::e($entry['description']) ?></h1><p><?= View::date($entry['entry_date']) ?> · <?= View::e($entry['entry_type']) ?><?= $entry['counterparty'] ? ' · ' . View::e($entry['counterparty']) : '' ?></p></div><div class="inline-actions"><?php if ($entry['status'] === 'DRAFT' && $entry['source_type'] === 'MANUAL'): ?><a class="button ghost" href="/accounting/journal/<?= (int) $entry['id'] ?>/edit">Modifica</a><form method="post" action="/accounting/journal/<?= (int) $entry['id'] ?>/post"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><button class="button primary" type="submit"><?= View::icon('check') ?> Contabilizza</button></form><?php endif; ?></div></section>

<section class="accounting-kpis entry-kpis"><article><span>Stato</span><strong><span class="badge status-<?= strtolower((string) $entry['status']) ?>"><?= View::e($entry['status']) ?></span></strong></article><article><span>Totale Dare</span><strong><?= View::money($entry['total_debit']) ?></strong></article><article><span>Totale Avere</span><strong><?= View::money($entry['total_credit']) ?></strong></article><article><span>Documento</span><strong><?= View::e($entry['document_number'] ?: '—') ?></strong></article></section>

<section class="card data-card"><div class="card-header"><div><span class="section-kicker">Dettaglio contabile</span><h2>Movimenti</h2></div><span class="score"><?= count($lines) ?></span></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Conto</th><th>Descrizione</th><th>Dare</th><th>Avere</th></tr></thead><tbody><?php foreach ($lines as $line): ?><tr><td><?= (int) $line['line_number'] ?></td><td class="primary-cell"><?= View::e($line['account_code']) ?><small><?= View::e($line['account_name']) ?></small></td><td><?= View::e($line['description'] ?: $entry['description']) ?></td><td><?= View::money($line['debit']) ?></td><td><?= View::money($line['credit']) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th colspan="3">Totali</th><th><?= View::money($entry['total_debit']) ?></th><th><?= View::money($entry['total_credit']) ?></th></tr></tfoot></table></div></section>
<?php if ($entry['notes']): ?><section class="card accounting-note"><span class="section-kicker">Note</span><p><?= nl2br(View::e($entry['notes'])) ?></p></section><?php endif; ?>
<?php if ($entry['status'] === 'DRAFT' && $entry['source_type'] === 'MANUAL'): ?><form method="post" action="/accounting/journal/<?= (int) $entry['id'] ?>/delete" data-confirm="Eliminare definitivamente questa bozza?"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><button class="button ghost danger-text" type="submit">Elimina bozza</button></form><?php endif; ?>
